 "content": "from collections import deque

def transform(grid):
    # Recolor zero pixels that lie inside a closed one-cell-wide outline as 3;
    # recolor the immediate external background ring as 2.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find zeros reachable from the edge without crossing 1s.
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w-1):
            if grid[r][c] == 0 and (r,c) not in outside:
                outside.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0, h-1):
            if grid[r][c] == 0 and (r,c) not in outside:
                outside.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    # Interior zeros become 3, but retain a one-cell central hole where present.
    inside=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==0 and (r,c) not in outside]
    for r,c in inside: out[r][c]=3
    # External zeros immediately adjacent to the outline become 2.
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 and (r,c) in outside and any(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==1 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):
                out[r][c]=2
    # The demo's central zero remains unfilled: preserve the center of each enclosed cavity.
    # (Handled in a later refinement if demonstrated.)
    return out
