    # Locate zero regions enclosed by the 1-pixel outlines.
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != 0 or (sr, sc) in seen:
                continue
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            cells, border = set(), set()
            touches_edge = False
            while q:
                r, c = q.popleft()
                cells.add((r, c))
                touches_edge |= r == 0 or c == 0 or r == h - 1 or c == w - 1
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if grid[nr][nc] == 1:
                            border.add((nr, nc))
                        elif (nr, nc) not in seen:
                            seen.add((nr, nc))
                            q.append((nr, nc))
            if not touches_edge and border:
                regions.append((cells, border))

    for cells, border in regions:
        # Color the inner rim of each closed outline with 3; deeper interior stays 0.
        for r, c in cells:
            if any((r + dr, c + dc) in border
                   for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc):
                out[r][c] = 3

        # Color the one-cell rectangular halo outside the outline's bounding box.
        r0 = min(r for r, c in border)
        r1 = max(r for r, c in border)
        c0 = min(c for r, c in border)
        c1 = max(c for r, c in border)
        for c in range(c0 - 1, c1 + 2):
            for r in (r0 - 1, r1 + 1):
                if 0 <= r < h and 0 <= c < w and grid[r][c] == 0:
                    out[r][c] = 2
        for r in range(r0 - 1, r1 + 2):
            for c in (c0 - 1, c1 + 1):
                if 0 <= r < h and 0 <= c < w and grid[r][c] == 0:
                    out[r][c] = 2
    return out
