                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in cells:
                        out[nr][nc] = 2

        # Complete diagonal corner pixels of the surrounding halo. Avoid coloring
        # isolated diagonal adjacency where the outline does not continue.
        pending = set()
        for r, c in outline:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
